using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IFacade : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Divide a surface into four-sided panels", SubCategory = "Panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Corners, outline, area, center and index of a panel", SubCategory = "Panels")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);

        [GrasshopperMethod("Planarity", "Planarity deviation of each panel", SubCategory = "Analysis")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Flat, cold-bent or custom by planarity deviation", SubCategory = "Analysis")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Area statistics of panels", SubCategory = "Analysis")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels")] List<Panel> panels);

        [GrasshopperMethod("Group Identical Panels", "Group panels with matching edge and diagonal lengths", SubCategory = "Fabrication")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-nest panel rectangles on sheets", SubCategory = "Fabrication")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 10.0)] double spacing,
            CancellationToken cancellationToken,
            IProgress<double> progress,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV cut list of panels, optionally written to a file", SubCategory = "Fabrication")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write);
    }

    public class FacadeCollection : IFacade
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (uCount < 1 || vCount < 1)
                throw new ArgumentException("U Count and V Count must be at least 1.");
            if (surface == null)
                throw new ArgumentException("Surface is missing.");

            var du = surface.Domain(0);
            var dv = surface.Domain(1);
            var pts = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
                for (int j = 0; j <= vCount; j++)
                    pts[i, j] = surface.PointAt(du.ParameterAt((double)i / uCount), dv.ParameterAt((double)j / vCount));

            var panels = new List<Panel>();
            var outlines = new List<Curve>();
            for (int i = 0; i < uCount; i++)
                for (int j = 0; j < vCount; j++)
                {
                    var p = new Panel(new[] { pts[i, j], pts[i + 1, j], pts[i + 1, j + 1], pts[i, j + 1] }, i * vCount + j);
                    panels.Add(p);
                    outlines.Add(p.Outline);
                }
            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null)
                throw new ArgumentException("Panel is missing.");
            return (panel.Corners.ToList(), panel.Outline, panel.Area, panel.Center, panel.Index);
        }

        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            var dev = panels.Select(p => p.PlanarityDeviation).ToList();
            var flat = dev.Select(d => d <= tolerance).ToList();
            int flatCount = flat.Count(f => f);
            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
                report.Warning($"{notFlat} of {panels.Count} panels are not flat.");
            return (dev, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            var types = new List<string>();
            int flat = 0, bent = 0, custom = 0;
            foreach (var p in panels)
            {
                double d = p.PlanarityDeviation;
                if (d <= tolerance) { types.Add("flat"); flat++; }
                else if (d <= 10 * tolerance) { types.Add("cold-bent"); bent++; }
                else { types.Add("custom"); custom++; }
            }
            return (types, flat, bent, custom);
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0)
                throw new ArgumentException("No panels.");
            var areas = panels.Select(p => p.Area).ToList();
            return (areas.Sum(), areas.Min(), areas.Max(), areas.Average());
        }

        private static (double[] Edges, double[] Diagonals) Signature(Panel p)
        {
            var e = new[] { p.Edge(0), p.Edge(1), p.Edge(2), p.Edge(3) };
            var d = new[] { p.Corners[0].DistanceTo(p.Corners[2]), p.Corners[1].DistanceTo(p.Corners[3]) };
            Array.Sort(e);
            Array.Sort(d);
            return (e, d);
        }

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var sigs = new List<(double[] Edges, double[] Diagonals)>();
            var reps = new List<Panel>();
            var groups = new List<int>();
            foreach (var p in panels)
            {
                var s = Signature(p);
                int g = -1;
                for (int k = 0; k < sigs.Count && g < 0; k++)
                {
                    bool same = true;
                    for (int i = 0; i < 4 && same; i++)
                        same = Math.Abs(s.Edges[i] - sigs[k].Edges[i]) <= tolerance;
                    for (int i = 0; i < 2 && same; i++)
                        same = Math.Abs(s.Diagonals[i] - sigs[k].Diagonals[i]) <= tolerance;
                    if (same) g = k;
                }
                if (g < 0)
                {
                    g = sigs.Count;
                    sigs.Add(s);
                    reps.Add(p);
                }
                groups.Add(g);
            }
            return (groups, reps.Count, reps);
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            CancellationToken cancellationToken, IProgress<double> progress, IBettaReport report)
        {
            return Task.Run(() =>
            {
                var parts = panels.Select(p => (w: p.Width, h: p.Height)).OrderByDescending(r => r.h).ToList();
                var outlines = new List<Curve>();
                var sheets = new List<int>();
                double placedArea = 0;
                int skipped = 0;

                int sheet = 0;
                double shelfX = spacing, shelfY = spacing, shelfH = 0;
                bool shelfOpen = false;
                bool sheetUsed = false;

                bool FitsEmpty(double w, double h) =>
                    w + 2 * spacing <= sheetWidth && h + 2 * spacing <= sheetHeight;

                void Place(double w, double h)
                {
                    double ox = sheet * (sheetWidth + 100) + shelfX;
                    var pl = new Polyline(new[]
                    {
                        new Point3d(ox, shelfY, 0), new Point3d(ox + w, shelfY, 0),
                        new Point3d(ox + w, shelfY + h, 0), new Point3d(ox, shelfY + h, 0),
                        new Point3d(ox, shelfY, 0)
                    });
                    outlines.Add(new PolylineCurve(pl));
                    sheets.Add(sheet);
                    placedArea += w * h;
                    shelfX += w + spacing;
                    sheetUsed = true;
                }

                for (int n = 0; n < parts.Count; n++)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    progress?.Report((double)n / parts.Count);
                    var (w, h) = parts[n];

                    if (!FitsEmpty(w, h) && !FitsEmpty(h, w)) { skipped++; continue; }

                    bool placed = false;
                    if (shelfOpen)
                    {
                        // current shelf: as is, then turned
                        foreach (var (pw, ph) in new[] { (w, h), (h, w) })
                            if (!placed && shelfX + pw + spacing <= sheetWidth && ph <= shelfH)
                            {
                                Place(pw, ph);
                                placed = true;
                            }
                    }
                    if (placed) continue;

                    // new shelf on current sheet
                    if (shelfOpen)
                    {
                        double newY = shelfY + shelfH + spacing;
                        foreach (var (pw, ph) in new[] { (w, h), (h, w) })
                            if (!placed && pw + 2 * spacing <= sheetWidth && newY + ph + spacing <= sheetHeight)
                            {
                                shelfY = newY; shelfX = spacing; shelfH = ph;
                                Place(pw, ph);
                                placed = true;
                            }
                    }
                    if (placed) continue;

                    // new sheet
                    if (sheetUsed) sheet++;
                    shelfOpen = true;
                    shelfY = spacing; shelfX = spacing;
                    var (fw, fh) = FitsEmpty(w, h) ? (w, h) : (h, w);
                    shelfH = fh;
                    Place(fw, fh);
                }

                int sheetCount = sheetUsed ? sheet + 1 : 0;
                double util = sheetCount == 0 ? 0 : placedArea / (sheetCount * sheetWidth * sheetHeight);
                if (skipped > 0)
                    report.Warning($"{skipped} panels do not fit on any sheet.");
                progress?.Report(1.0);
                return (outlines, sheets, sheetCount, util);
            }, cancellationToken);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Path is empty; cannot write the cut list.");

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels)
                sb.Append(p.Index.ToString(inv)).Append(',')
                  .Append(p.Width.ToString("R", inv)).Append(',')
                  .Append(p.Height.ToString("R", inv)).Append(',')
                  .Append(p.Area.ToString("R", inv)).Append(',')
                  .Append(p.PlanarityDeviation.ToString("R", inv)).Append('\n');
            var csv = sb.ToString();

            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}

